set -e; cat > /app/media_exercise.js <<'JS'
const Module=require('module'),fs=require('fs');
const events=[];
const db={deleteObjectFields:async(key,fields)=>events.push({operation:'deleteObjectFields',key,fields})};
const file={delete:async(path)=>events.push({operation:'file.delete',path})};
const original=Module._load;
Module._load=function(request,parent){const source=(parent&&parent.filename)||'';if(source.endsWith('/src/user/picture.js')||source.endsWith('/src/groups/cover.js')){if(request==='../database')return db;if(request==='../file')return file;if(request==='../image')return {};if(request==='../meta')return {config:{}};if(request==='../plugins')return {hooks:{hasListeners:()=>false}};}return original.apply(this,arguments)};
(async()=>{const kind=process.argv[2];if(kind==='user'){const User={};require('/app/src/user/picture.js')(User);await User.removeCoverPicture({uid:4101});}else{const Groups={};require('/app/src/groups/cover.js')(Groups);await Groups.removeCover({groupName:'research-board'});}if(events.length!==1||events[0].operation!=='deleteObjectFields')throw Error('unexpected adapter event');fs.writeFileSync('/app/'+kind+'-database-event.json',JSON.stringify(events[0])+'\n');console.log(kind+'_reference_removed key='+events[0].key+' fields='+events[0].fields.join(','));})().catch(e=>{console.error(e);process.exit(1)});
JS
node /app/media_exercise.js user
